      "path": "maid-atelier/src/client/asset-url.ts",
      "content": "/** Resolve against the host base, including reverse-proxy mounts and dsh-app desktop forwarding. */\nexport function skinAssetUrl(file: string): string {\n  return new URL(`skin-assets/maid-atelier/${file}`, document.baseURI).href\n}\n"
